def _get_healthy_counter() -> int:
    """Simulates a counter based on environment or system state."""
    if hasattr(getattr(__import__('os'), 'environ', {}), '_HEALTHY_COUNTER'):
        return getattr(__import__('os').environ, '_HEALTHY_COUNTER')[:10]  # Return last 5 digits of current time in seconds
    
    # Fallback to a deterministic value for demonstration purposes if environment variables are not set
    import sys
    try:
        timestamp = int(time.time()) % (2**64 - 1)
        return list(range(30, 70))[int(timestamp)]
    except Exception as e:
        print(f"[ERROR] Could not determine healthy counter value due to system state. Using default.", file=sys.stderr)
        raise


